import{z as E,x as i,o as t,c as A,q as s,j as n,D as B,d as r,s as l,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"BTB 与返回栈","description":"","frontmatter":{"title":"BTB 与返回栈","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/btb-ras.md","filePath":"cs/btb-ras.md","lastUpdated":1791413859000}'),p={name:"cs/btb-ras.md"};function c(C,a,T,S,m,f){const o=i("Mermaid");return t(),A("div",null,[a[2]||(a[2]=s('<h1 id="btb-与返回栈" tabindex="-1">BTB 与返回栈 <a class="header-anchor" href="#btb-与返回栈" aria-label="Permalink to &quot;BTB 与返回栈&quot;">​</a></h1><div class="epigraph"><p>方向猜对还不够：间接跳转的目标每次可能不同，返回地址却几乎总是配对的那一次调用。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/control-hazard-predict">上一课</a>让 IF 按一位计数器或静态规则猜方向，核对失败则冲刷。条件分支的目标是 PC 加立即数，算出来即可。本课不重讲饱和计数器。缺口是：间接跳转与 <code>ret</code> 的<strong>目标地址</strong>在译码前未知，猜方向帮不上忙。本课只交出分支目标缓冲（BTB）与返回地址栈（RAS）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>jalr</code>、虚函数、<code>switch</code> 跳表：下一 PC 来自寄存器，五级里要到 ID 甚至 EX 才有值。若 IF 只准备「成功/失败」两位，仍不知道往哪取。返回指令的目标倒是历史：对应 <code>jal</code> 当时的 PC+4。缺口不是更宽的条件比较，而是<strong>用 PC 索引一张目标表，并用栈专门记返回地址</strong>。</p><p>上一课明确不把间接跳转预测表铺开。本课补上这一块，仍不引入两级模式历史。</p><p><span class="marginnote">BTB 命中且预测成功，IF 下一拍就能从目标取指，不必等 ALU 算地址。RAS 深度有限，递归过深会溢出，只能当提示。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>BTB：按取指 PC 索引（可组相联），条目存标签、预测目标、可选一位有效。命中则用存下的目标当下一 PC；EX 核对，错则冲刷并更新该条目。未命中则按顺序取指或按方向预测走立即数目标。</p><p>RAS：<code>jal</code>/<code>jalr</code> 用作调用时把返回地址压栈；译码到返回时弹栈当预测目标。与 BTB 可并行：返回优先信 RAS。</p><p><span class="marginnote">RAS 可以想象成一摞盘子：每进入一层调用压一只盘子，盘底写着回程地址；返回时只拿最上面那只——最后进的最先出，恰好就是函数嵌套的顺序。递归过深盘子架放不下（表项有限），预测就退化为瞎猜，但不会错。</span></p>',11)),(t(),n(d,null,{default:B(()=>[l(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PC%5B%22%E5%8F%96%E6%8C%87%20PC%22%5D%20--%3E%20BTB%5B%22BTB%20%E6%9F%A5%E7%9B%AE%E6%A0%87%22%5D%0A%20%20PC%20--%3E%20RAS%5B%22%E8%AF%91%E7%A0%81%E4%B8%BA%E8%BF%94%E5%9B%9E%E5%88%99%E5%BC%B9%20RAS%22%5D%0A%20%20BTB%20--%3E%20IF%5B%22IF%20%E7%94%A8%E9%A2%84%E6%B5%8B%20PC%22%5D%0A%20%20RAS%20--%3E%20IF%0A%20%20IF%20--%3E%20CHK%5B%22EX%20%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20CHK%20--%3E%7C%22%E9%94%99%22%7C%20FLUSH%5B%22%E5%86%B2%E5%88%B7%E5%B9%B6%E6%9B%B4%E6%96%B0%20BTB%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"控制冒险的损失拍数里，「目标未知」与「方向未知」是两项。BTB 把前者从「等 EX」降到「等 BTB SRAM」，命中时与条件预测叠用。RAS 利用调用/返回的 LIFO，准确率通常高于把返回当成普通间接跳转塞进 BTB——BTB 会被不同调用点别名污染。",-1)),a[5]||(a[5]=e("p",null,"BTB 本身是预测器状态，不是 ISA 寄存器。上下文切换不必保存；冷 BTB 只让误预测暂时升高。",-1)),a[6]||(a[6]=e("p",null,"下图回答一个具体问题：两层嵌套调用返回时，RAS 的压与弹如何逐条对上。",-1)),(t(),n(d,null,{default:B(()=>[l(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22main%20%E8%B0%83%20f%EF%BC%9A%E5%8E%8B%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%200x108%22%5D%20--%3E%20S1%5B%22RAS%EF%BC%9A0x108%22%5D%0A%20%20C2%5B%22f%20%E8%B0%83%20g%EF%BC%9A%E5%8E%8B%200x208%22%5D%20--%3E%20S2%5B%22RAS%EF%BC%9A0x208%2C%200x108%22%5D%0A%20%20R1%5B%22g%20%E6%89%A7%E8%A1%8C%20ret%EF%BC%9A%E5%BC%B9%200x208%EF%BC%8C%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20S3%5B%22RAS%EF%BC%9A0x108%22%5D%0A%20%20R2%5B%22f%20%E6%89%A7%E8%A1%8C%20ret%EF%BC%9A%E5%BC%B9%200x108%EF%BC%8C%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20S4%5B%22RAS%EF%BC%9A%E7%A9%BA%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">数字实例：main 在 0x104 处调 f（返回地址 0x108），f 在 0x204 处调 g（返回地址 0x208）。g 的 <code>ret</code> 弹得 0x208，f 的 <code>ret</code> 弹得 0x108，两次全中。若只靠 BTB 记「g 里这条 <code>ret</code> 上次跳哪」，换个调用者目标就变——同一 PC 多个目标互相覆盖，正是 BTB 被污染的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入竞赛预测、不引入间接跳转的完整历史（ITTAGE 一类）。特权态 <code>eret</code> 的目标来自 CSR，不走用户 RAS。异常冲刷时 RAS 可能失配，实现可选择恢复或清空；精确性仍由<a href="/cs/pipeline-exception">流水线异常</a>的提交点保证，预测结构可以错。</p><p>后课默认：IF 的下一 PC 来自顺序、条件立即数、BTB 或 RAS。方向仍可用简单计数器；更准的相关预测是下一课。</p><p><span class="marginnote">常见误区：初学者担心「预测器猜错会算错程序」。BTB 和 RAS 只是提示：真正的目标地址在 EX 阶段核对，猜错就冲刷流水线重来。预测器可以随便错，代价只有时间；正确性由流水线的提交机制保证，这也是异常精确性的同一套思路。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BTB 缓存间接/分支目标，让 IF 不必等算出地址。</li><li>RAS 按调用栈弹返回地址，比把 <code>ret</code> 塞进 BTB 更稳。</li><li>两级与锦标赛预测是后课的缺口。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> 分支目标缓冲与返回栈。</li></ul>',7))])}const b=E(p,[["render",c]]);export{u as __pageData,b as default};
